// @ts-check
import withNuxt from './.nuxt/eslint.config.mjs'

export default withNuxt(
  {
    // app/components/ui is generated by the shadcn-vue CLI and re-generated on
    // upgrade — linting it only produces churn we'd have to reapply.
    ignores: [
      'scripts/**',
      'migrations/**',
      'docker/**',
      'shared/pocketbase/**',
      'app/components/ui/**',
      'packages/*/dist/**',
      // A single hand-written HTML page with an inline module — not part of the
      // app's build, and the Nuxt config's rules do not describe it.
      'examples/**',
    ],
  },
  {
    rules: {
      // oxfmt is the formatter, and it writes void elements self-closing.
      // Leaving this rule on means every `npm run format` reintroduces a
      // warning that `npm run lint:fix` then undoes — the two tools fight and
      // the working tree never settles.
      'vue/html-self-closing': 'off',
    },
  },
)
